// Generic semantic text adapter. It does not contain a known string or a
// screenshot oracle: callers supply arbitrary text and may optionally attach
// a font-derived image surface generated by the Qt build-time helper.
export function applyFontRasterAdapter(node, { text, surface = null, preserveDomText = true } = {}) {
  if (!(node instanceof HTMLElement) || typeof text !== 'string') {
    throw new TypeError('text adapter requires an HTMLElement and a string');
  }
  if (preserveDomText) node.textContent = text;
  node.dataset.sourceText = text;
  if (surface?.src) {
    const image = document.createElement('img');
    image.src = surface.src;
    image.alt = '';
    image.setAttribute('aria-hidden', 'true');
    image.className = 'font-derived-surface';
    image.setAttribute('data-surface-text', text);
    node.append(image);
  }
  return node;
}

export function describeTextSurface(node, text) {
  return {
    text,
    semantic_text_present: node?.textContent === text,
    source_screenshot_used: false,
    font_derived_surface: Boolean(node?.querySelector('.font-derived-surface')),
  };
}
